SELECT ?encoder ?price
WHERE {
  ?supplier a pv:Supplier ;
            pv:addressCountryCode "FR"^^xsd:string ; 
            pv:addressLocality ?locality .
  OPTIONAL { ?supplier wgs84:lat ?lat . }
  OPTIONAL { ?supplier wgs84:long ?long . }

  ?encoder a pv:Hardware ;
             pv:id "Encoder"^^xsd:string ;
             pv:name "Encoder"^^xsd:string ;
             pv:hasSupplier ?supplier .

  ?price a pv:Price ;
           pv:value ?value .
  FILTER (?encoder = <http://ld.company.org/prod-instances/prodi:prod-cat-Encoder> && 
          ?price = ?encoder/pv:prices/0/pv:value)
}
ORDER BY DESC(?value)

