WHERE {
  ?product a pv:ProductCategory .
  ?product rdfs:label "Oscillator"@en .
  ?product pv:price ?price .
  ?price pv:currency ?currency .
  OPTIONAL { 
    ?prod a pv:Hardware; pv:price ?p; 
          a pv:ProductCategory; rdfs:label "Oscillator"@en;
          pv:price ?minPrice .
